#!/usr/bin/env perl
use strict;
use warnings;

## [: zenka.util.threshold-checker # name = threshold-checker # descr = reads threshold from config and warns if value exceeds it ]

# %code hash is populated by bin/Protocol-7 via perlmod.load
# this file is the module body — no sub {} declarations

sub check_threshold {
    my ($value, $config, $threshold_key) = @ARG;

    # default threshold of 30 if not provided in config
    my $threshold = 30;

    if (defined($config) && ref($config) eq 'HASH') {
        if (exists($config->{$threshold_key})) {
            $threshold = $config->{$threshold_key};
        }
    }

    # warn if value exceeds threshold
    if ($value > $threshold) {
        <[base.logs]>->(
            1,  # level = default (1)
            "threshold exceeded: value %d exceeds threshold %d",
            $value,
            $threshold,
        );
    }

    return { mode => qw| true |, data => $threshold };
}

# --- module entry point ---
1;
```

**Usage example:**

```perl
<[zenka.util.threshold-checker]>->(
    $value_to_check,
    $config_hash,
    'max_value',
);
```

**How it works:**
- Reads a threshold key from the provided config hash (defaults to 30)
- Compares the input value against the threshold
- Logs a warning (level 1) if the value exceeds the threshold
- Returns a success hash with the effective threshold value

**Key P7 patterns used:**
- `my ($value, $config, $threshold_key) = @ARG` — uses `use English` alias for `@_`
- `<[base.logs]>->( $level, $format, @args )` — P7's logging interface
- `ref($config) eq 'HASH'` — type check before hash dereference
- Returns `{ mode => qw| true |, data => $result }` — P7 success contract
